<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,reactive,ref,watch} from 'vue';
import Icon from './Icon.vue';
type Item={id:string;[key:string]:any};
type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
const props=defineProps<{section:string;request:Request;readonly:boolean;memberId?:string}>();
const emit=defineEmits<{refresh:[];support:[value:any]}>();
const rows=ref<Item[]>([]),plans=ref<Item[]>([]),departments=ref<Item[]>([]),operators=ref<Item[]>([]),summary=ref<Item|null>(null),access=ref<Item[]>([]),resourceAlerts=ref<Item[]>([]);
const busy=ref(false),error=ref(''),success=ref(''),dialog=ref(''),editing=ref<Item|null>(null),requestKey=ref(''),modal=ref<HTMLElement|null>(null);let focus:HTMLElement|null=null,previousOverflow:string|null=null;
function restoreScroll(){if(previousOverflow!==null){document.body.style.overflow=previousOverflow;previousOverflow=null;}}
const roleNames:Record<string,string>={TENANT_ADMIN:'企业管理员',SALES_MANAGER:'销售经理',SALES:'销售',VIEWER:'只读成员'};
const scopeNames:Record<string,string>={ALL:'本企业全部记录',DEPARTMENT:'本部门记录（不含子部门）',OWN_SHARED:'本人记录（客户另含共享）'};
const fieldNames:Record<string,string>={NONE:'不可见',READ:'只读',WRITE:'可读写'};
const titles:Record<string,string>={members:'组织成员',departments:'部门管理',policies:'角色与客户权限','sales-rules':'销售资源规则',billing:'套餐与订阅',support:'运营支持授权',audits:'企业管理记录','platform-tenants':'企业与订阅','platform-plans':'套餐管理','platform-renewals':'人工续费审核','platform-accounts':'登录账号','platform-support':'获批支持访问','platform-audits':'平台操作记录'};
const descriptions:Record<string,string>={members:'创建真实登录账号，管理成员归属、业务档案、角色与启用状态。',departments:'维护企业组织结构，停用前需调整有效成员和子部门。',policies:'分别配置业务模块、报表、数据交换及附件权限；关联资料继续受客户范围限制。','sales-rules':'按销售人员设置线索与客户保有量、超限处理方式和长期未跟进判断周期。',billing:'查看实际用量和订阅有效期，提交人工续费申请。',support:'你决定运营人员何时、以什么范围查看企业客户。',audits:'管理动作已记录到服务端，密码不会出现在记录中。','platform-tenants':'开通企业，调整套餐并管理使用状态。','platform-plans':'按月定价，配置成员、客户及附件容量。当前均为测试套餐。','platform-renewals':'实际收到款项后填写凭据编号，再确认延长订阅。','platform-accounts':'管理全局登录账号；重置密码或绑定核验邮箱会撤销该账号的全部会话。','platform-support':'只能进入企业管理员明确授权且仍有效的只读工作区。','platform-audits':'查看平台与企业管理动作，不包含客户业务正文。'};
const form=reactive({code:'',name:'',industry:'',planId:'',trialDays:14,adminUsername:'',adminName:'',initialPassword:'',newPassword:'',price:'199.00',seatLimit:10,customerLimit:1000,active:true,status:'ACTIVE',departmentId:'',parentId:'',username:'',roles:['SALES'],employeeCode:'',jobTitle:'',salesRegion:'',serviceStatus:'AVAILABLE',successorMemberId:'',months:3,paymentReference:'',reason:'',operatorUserId:'',hours:2,allowCredit:false,allowDescription:false,storageMB:1024,recoveryEmail:'',configurationEnabled:true,portalEnabled:true,aiEnabled:true,aiMonthlyRunLimit:100});
const activePlans=computed(()=>plans.value.filter(p=>p.active));
function money(value:number){return '¥'+(value/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function date(value:string){return value?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)):'—';}
function tenantState(t:Item){return t.status==='SUSPENDED'?'已暂停':new Date(t.subscriptionEnd)<=new Date()?'到期只读':'正常使用';}
function grantState(g:Item){return g.revokedAt?'已撤销':new Date(g.expiresAt)<=new Date()?'已到期':'授权有效';}
function cents(value:string){if(!/^(0|[1-9]\d{0,6})(\.\d{1,2})?$/.test(value.trim()))throw new Error('价格请输入最多两位小数的非负金额');const [whole,fraction='']=value.trim().split('.');return Number(whole)*100+Number(fraction.padEnd(2,'0'));}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作未完成';}finally{busy.value=false;}}
async function load(){const api=props.request;
 if(props.section==='platform-tenants'){[rows.value,plans.value]=await Promise.all([api<Item[]>('/platform/tenants'),api<Item[]>('/platform/plans')]);}
 else if(props.section==='platform-plans')rows.value=await api<Item[]>('/platform/plans');
 else if(props.section==='platform-renewals')rows.value=await api<Item[]>('/platform/renewals');
 else if(props.section==='platform-accounts')rows.value=await api<Item[]>('/platform/accounts');
 else if(props.section==='platform-support')rows.value=await api<Item[]>('/platform/support/grants');
 else if(props.section==='platform-audits')rows.value=await api<Item[]>('/platform/audits');
 else if(props.section==='members'){[rows.value,departments.value,summary.value]=await Promise.all([api<Item[]>('/workspace/members'),api<Item[]>('/workspace/departments'),api<Item>('/workspace/summary')]);}
 else if(props.section==='departments')rows.value=await api<Item[]>('/workspace/departments');
 else if(props.section==='sales-rules'){[rows.value,resourceAlerts.value]=await Promise.all([api<Item[]>('/workspace/sales-resource-policies'),api<Item[]>('/workspace/resource-alerts')]);}
 else if(props.section==='policies')rows.value=await api<Item[]>('/workspace/role-policies');
 else if(props.section==='billing'){[summary.value,rows.value]=await Promise.all([api<Item>('/workspace/summary'),api<Item[]>('/workspace/renewals')]);}
 else if(props.section==='support'){[rows.value,operators.value]=await Promise.all([api<Item[]>('/workspace/support/grants'),api<Item[]>('/workspace/support/operators')]);}
 else rows.value=await api<Item[]>('/workspace/audits');
}
function open(type:string,item?:Item){editing.value=item??null;dialog.value=type;requestKey.value=crypto.randomUUID();error.value='';Object.assign(form,{code:'',name:'',industry:'',planId:activePlans.value[0]?.id??'',trialDays:14,adminUsername:'',adminName:'',initialPassword:'',newPassword:'',price:'199.00',seatLimit:10,customerLimit:1000,active:true,status:'ACTIVE',departmentId:'',parentId:'',username:'',roles:['SALES'],employeeCode:'',jobTitle:'',salesRegion:'',serviceStatus:'AVAILABLE',successorMemberId:'',months:3,paymentReference:'',reason:'',operatorUserId:operators.value[0]?.id??'',hours:2,allowCredit:false,allowDescription:false,storageMB:1024,recoveryEmail:'',configurationEnabled:true,portalEnabled:true,aiEnabled:true,aiMonthlyRunLimit:100});if(item){Object.assign(form,{code:item.code??'',name:item.name??item.displayName??'',planId:item.planId??'',price:((item.monthlyPriceCents??19900)/100).toFixed(2),seatLimit:item.seatLimit??10,customerLimit:item.customerLimit??1000,active:item.active??true,status:item.status??'ACTIVE',departmentId:item.departmentId??'',parentId:item.parentId??'',username:item.username??'',roles:[...(item.roles??['SALES'])],employeeCode:item.employeeCode??'',jobTitle:item.jobTitle??'',salesRegion:item.salesRegion??'',serviceStatus:item.serviceStatus??'AVAILABLE',successorMemberId:props.memberId===item.id?'':props.memberId??'',storageMB:Math.round((item.storageLimitBytes??1073741824)/1048576),recoveryEmail:item.recoveryEmail??'',configurationEnabled:item.configurationEnabled??true,portalEnabled:item.portalEnabled??true,aiEnabled:item.aiEnabled??true,aiMonthlyRunLimit:item.aiMonthlyRunLimit??100});}}
function close(){if(!busy.value)dialog.value='';}
async function save(){return run(async()=>{const api=props.request,id=editing.value?.id,version=editing.value?.version??0,headers={'Idempotency-Key':requestKey.value};
 if(dialog.value==='tenant')await api('/platform/tenants','POST',{code:form.code,name:form.name,industry:form.industry,planId:form.planId,trialDays:form.trialDays,adminUsername:form.adminUsername,adminName:form.adminName,initialPassword:form.initialPassword},headers);
 else if(dialog.value==='subscription')await api('/platform/tenants/'+id,'PATCH',{planId:form.planId,status:form.status,expectedVersion:version});
 else if(dialog.value==='plan')await api('/platform/plans'+(id?'/'+id:''),id?'PATCH':'POST',{code:form.code,name:form.name,monthlyPriceCents:cents(form.price),seatLimit:form.seatLimit,customerLimit:form.customerLimit,storageLimitBytes:Math.round(form.storageMB*1048576),configurationEnabled:form.configurationEnabled,portalEnabled:form.portalEnabled,aiEnabled:form.aiEnabled,aiMonthlyRunLimit:form.aiMonthlyRunLimit,active:form.active,expectedVersion:version},headers);
 else if(dialog.value==='member'){const base={name:form.name,departmentId:form.departmentId||null,roles:form.roles,employeeCode:form.employeeCode,jobTitle:form.jobTitle,salesRegion:form.salesRegion,serviceStatus:form.serviceStatus};if(id)await api('/workspace/members/'+id,'PATCH',{...base,status:form.status,successorMemberId:form.status==='DISABLED'?form.successorMemberId||null:null,expectedVersion:version});else await api('/workspace/members','POST',{...base,username:form.username,initialPassword:form.initialPassword},headers);}
 else if(dialog.value==='department')await api('/workspace/departments'+(id?'/'+id:''),id?'PATCH':'POST',{name:form.name,parentId:form.parentId||null,active:form.active,expectedVersion:version},headers);
 else if(dialog.value==='renewal')await api('/workspace/renewals','POST',{months:form.months},headers);
 else if(dialog.value==='decision')await api('/platform/renewals/'+id+'/decision','POST',{status:form.status,paymentReference:form.paymentReference,reason:form.reason,expectedVersion:version});
 else if(dialog.value==='grant')await api('/workspace/support/grants','POST',{operatorUserId:form.operatorUserId,hours:form.hours,reason:form.reason,allowCredit:form.allowCredit,allowDescription:form.allowDescription},headers);
 else if(dialog.value==='recovery')await api('/platform/accounts/'+id+'/recovery-email','POST',{email:form.recoveryEmail,expectedAuthVersion:editing.value?.authVersion??0,reason:form.reason});
 else if(dialog.value==='reset')await api('/platform/accounts/'+id+'/password-reset','POST',{newPassword:form.newPassword});
 dialog.value='';form.initialPassword='';form.newPassword='';await load();emit('refresh');success.value='已保存到服务端';});}
function savePolicy(item:Item){return run(async()=>{await props.request('/workspace/role-policies/'+item.roleCode,'PATCH',{canRead:item.canRead,canWrite:item.canWrite,recordScope:item.recordScope,creditAccess:item.creditAccess,descriptionAccess:item.descriptionAccess,canShare:item.canShare,contactCanRead:item.contactCanRead,contactCanWrite:item.contactCanWrite,leadCanRead:item.leadCanRead,leadCanWrite:item.leadCanWrite,opportunityCanRead:item.opportunityCanRead,opportunityCanWrite:item.opportunityCanWrite,taskCanRead:item.taskCanRead,taskCanWrite:item.taskCanWrite,activityCanRead:item.activityCanRead,activityCanWrite:item.activityCanWrite,reportCanRead:item.reportCanRead,exportCanRead:item.exportCanRead,importCanWrite:item.importCanWrite,attachmentCanRead:item.attachmentCanRead,attachmentCanWrite:item.attachmentCanWrite,productCanRead:item.productCanRead,productCanWrite:item.productCanWrite,quoteCanRead:item.quoteCanRead,quoteCanWrite:item.quoteCanWrite,quotePdfCanExport:item.quotePdfCanExport,quoteCanApprove:item.quoteCanApprove,contractCanRead:item.contractCanRead,contractCanWrite:item.contractCanWrite,contractCanAmend:item.contractCanAmend,receiptCanRead:item.receiptCanRead,receiptCanWrite:item.receiptCanWrite,receiptCanConfirm:item.receiptCanConfirm,receiptCanReverse:item.receiptCanReverse,tradeCanExport:item.tradeCanExport,aiCanUse:item.aiCanUse,aiCanReview:item.aiCanReview,expectedVersion:item.version});await load();emit('refresh');success.value='权限已更新，下次请求立即生效';});}
function saveResourceRule(item:Item){return run(async()=>{await props.request('/workspace/sales-resource-policies/'+item.memberId,'PUT',{leadLimit:item.leadLimit,customerLimit:item.customerLimit,overflowAction:item.overflowAction,leadStaleDays:item.leadStaleDays,customerStaleDays:item.customerStaleDays,expectedVersion:item.version});await load();success.value='销售资源规则已保存并立即生效';});}
function readResourceAlert(item:Item){return run(async()=>{await props.request('/workspace/resource-alerts/'+item.id+'/read','POST');await load();success.value='预警已标记处理';});}
function normalizeModules(p:Item){if(!p.contractCanRead){p.contractCanWrite=false;p.contractCanAmend=false;p.receiptCanRead=false;p.receiptCanWrite=false;p.receiptCanConfirm=false;p.receiptCanReverse=false;p.tradeCanExport=false;}if(!p.contractCanWrite)p.contractCanAmend=false;if(!p.receiptCanRead){p.receiptCanWrite=false;p.receiptCanConfirm=false;p.receiptCanReverse=false;}if(!p.contactCanRead)p.contactCanWrite=false;if(!p.leadCanRead)p.leadCanWrite=false;if(!p.opportunityCanRead)p.opportunityCanWrite=false;if(!p.taskCanRead)p.taskCanWrite=false;if(!p.activityCanRead)p.activityCanWrite=false;if(!p.attachmentCanRead)p.attachmentCanWrite=false;if(!p.productCanRead)p.productCanWrite=false;if(!p.quoteCanRead){p.quoteCanWrite=false;p.quotePdfCanExport=false;p.quoteCanApprove=false;}}
function normalizePolicy(p:Item){if(!p.canRead)p.canWrite=false;if(!p.canWrite){p.canShare=false;if(p.creditAccess==='WRITE')p.creditAccess='READ';if(p.descriptionAccess==='WRITE')p.descriptionAccess='READ';}}
function cancel(item:Item){return run(async()=>{await props.request('/workspace/renewals/'+item.id+'/cancel','POST');await load();success.value='续费申请已取消';});}
function revoke(item:Item){return run(async()=>{await props.request('/workspace/support/grants/'+item.id+'/revoke','POST');await load();success.value='支持授权已撤销';});}
function enter(item:Item){return run(async()=>{const value=await props.request('/platform/support/'+item.id+'/enter','POST');emit('support',value);});}
function showAccess(item:Item){return run(async()=>{access.value=await props.request<Item[]>('/workspace/support/grants/'+item.id+'/access');editing.value=item;dialog.value='access';});}
watch(dialog,async value=>{if(value){focus=document.activeElement as HTMLElement;if(previousOverflow===null)previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();modal.value?.querySelector<HTMLElement>('button:not(:disabled),input:not(:disabled)')?.focus({preventScroll:true});}else{restoreScroll();form.initialPassword='';form.newPassword='';focus?.focus({preventScroll:true});}});
function keys(event:KeyboardEvent){if(!dialog.value)return;if(event.key==='Escape'){close();return;}if(event.key==='Tab'){const nodes=modal.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}
onMounted(()=>{document.addEventListener('keydown',keys);run(load);});onUnmounted(()=>{document.removeEventListener('keydown',keys);restoreScroll();});
</script>

<template>
 <div class="admin-area">
  <div class="page-heading"><div><span class="eyebrow">{{section.startsWith('platform-')?'SAAS OPERATOR CONSOLE':'YOUR WORKSPACE ADMINISTRATION'}}</span><h1>{{titles[section]}}</h1><p>{{descriptions[section]}}</p></div><div class="admin-heading-actions"><button class="btn secondary" :disabled="busy" @click="run(load)"><Icon name="refresh" :size="16"/>刷新</button><button v-if="section==='platform-tenants'" class="btn primary" :disabled="busy" @click="open('tenant')"><Icon name="plus" :size="17"/>开通企业</button><button v-if="section==='platform-plans'" class="btn primary" :disabled="busy" @click="open('plan')"><Icon name="plus" :size="17"/>创建套餐</button><button v-if="section==='members'" class="btn primary" :disabled="busy||readonly" @click="open('member')"><Icon name="plus" :size="17"/>新增成员</button><button v-if="section==='departments'" class="btn primary" :disabled="busy||readonly" @click="open('department')"><Icon name="plus" :size="17"/>新增部门</button><button v-if="section==='support'" class="btn primary" :disabled="busy||readonly||!operators.length" @click="open('grant')"><Icon name="plus" :size="17"/>授权只读支持</button></div></div>
  <div v-if="error&&!dialog" class="admin-alert error" role="alert">{{error}}</div><div v-if="success" class="admin-alert ok" role="status">{{success}}</div>
  <template v-if="section==='billing'&&summary"><div class="admin-summary"><section class="card"><span>当前套餐</span><h2>{{summary.planName}}</h2><strong>{{money(summary.monthlyPriceCents)}} <small>/ 月</small></strong><p>{{date(summary.subscriptionEnd)}} 到期</p></section><section class="card"><span>有效成员</span><h2>{{summary.activeMemberCount}} <small>/ {{summary.seatLimit}}</small></h2><p>停用成员后释放名额，重新启用时再次检查额度。</p></section><section class="card"><span>客户用量</span><h2>{{summary.customerCount}} <small>/ {{summary.customerLimit}}</small></h2><p>额度在服务端写入事务中检查。</p></section></div><section class="admin-note"><Icon name="file"/><div><strong>附件容量：{{(summary.attachmentBytes/1048576).toFixed(2)}} / {{Math.round(summary.storageLimitBytes/1048576)}} MB</strong><p>单个文件最多5MB；删除后释放套餐容量。</p></div></section><section class="admin-note"><Icon name="wallet"/><div><strong>人工续费流程</strong><p>提交申请后，由运营人员核实实际收款并确认。当前没有在线扣款。</p></div><button class="btn primary" :disabled="busy||rows.some(r=>r.status==='PENDING')" @click="open('renewal')">申请续费</button></section></template>
  <div v-if="section==='members'&&summary" class="admin-note"><Icon name="users"/><div><strong>{{summary.activeMemberCount}} / {{summary.seatLimit}} 位有效成员</strong><p>新账号首次登录需修改初始密码。此处不会发送邀请邮件。</p></div></div>
  <div v-if="section==='policies'" class="admin-note"><Icon name="shield"/><div><strong>按角色配置业务模块和数据权限</strong><p>多角色的读取和写入范围分别合并；只读角色不会扩大另一角色的写入范围。“本部门”不包含子部门。</p></div></div>
  <section v-if="section==='policies'" class="card admin-ai-policy"><div><h2>AI 使用与复核权限</h2><p>AI 仍会按每位成员原有的客户、商机和工单权限读取记录。复核权限只能授予企业管理员或销售经理。</p></div><article v-for="p in rows" :key="'ai-'+p.roleCode"><strong>{{roleNames[p.roleCode]}}</strong><label><input v-model="p.aiCanUse" type="checkbox" :disabled="busy||readonly||p.roleCode==='VIEWER'" @change="!p.aiCanUse&&(p.aiCanReview=false)"/>使用 AI</label><label><input v-model="p.aiCanReview" type="checkbox" :disabled="busy||readonly||!p.aiCanUse||!['TENANT_ADMIN','SALES_MANAGER'].includes(p.roleCode)"/>复核企业记录</label><button class="text-button" :disabled="busy||readonly" @click="savePolicy(p)">保存</button></article></section>
  <section v-if="section==='policies'" class="admin-policies"><article v-for="p in rows" :key="p.roleCode" class="card policy-card"><div class="policy-title"><h2>{{roleNames[p.roleCode]}}</h2><span class="badge neutral">版本 {{p.version}}</span></div><div class="admin-policy-checks"><label><input v-model="p.canRead" type="checkbox" :disabled="busy||readonly" @change="normalizePolicy(p)"/>读取客户</label><label><input v-model="p.canWrite" type="checkbox" :disabled="busy||readonly||!p.canRead||p.roleCode==='VIEWER'" @change="normalizePolicy(p)"/>新增与编辑客户</label><label><input v-model="p.canShare" type="checkbox" :disabled="busy||readonly||!p.canWrite"/>管理获授权客户共享</label></div><div class="admin-policy-checks"><label><input v-model="p.contactCanRead" type="checkbox" :disabled="busy||readonly" @change="normalizeModules(p)"/>读取联系人</label><label><input v-model="p.contactCanWrite" type="checkbox" :disabled="busy||readonly||!p.contactCanRead||p.roleCode==='VIEWER'"/>新增与编辑联系人</label><label><input v-model="p.leadCanRead" type="checkbox" :disabled="busy||readonly" @change="normalizeModules(p)"/>读取线索</label><label><input v-model="p.leadCanWrite" type="checkbox" :disabled="busy||readonly||!p.leadCanRead||p.roleCode==='VIEWER'"/>新增与编辑线索</label></div><div class="admin-policy-checks"><label><input v-model="p.opportunityCanRead" type="checkbox" :disabled="busy||readonly" @change="normalizeModules(p)"/>读取商机</label><label><input v-model="p.opportunityCanWrite" type="checkbox" :disabled="busy||readonly||!p.opportunityCanRead||p.roleCode==='VIEWER'"/>管理商机与阶段</label><label><input v-model="p.taskCanRead" type="checkbox" :disabled="busy||readonly" @change="normalizeModules(p)"/>读取待办</label><label><input v-model="p.taskCanWrite" type="checkbox" :disabled="busy||readonly||!p.taskCanRead||p.roleCode==='VIEWER'"/>管理待办</label><label><input v-model="p.activityCanRead" type="checkbox" :disabled="busy||readonly" @change="normalizeModules(p)"/>读取跟进</label><label><input v-model="p.activityCanWrite" type="checkbox" :disabled="busy||readonly||!p.activityCanRead||p.roleCode==='VIEWER'"/>新增跟进</label></div><div class="admin-policy-checks"><label><input v-model="p.reportCanRead" type="checkbox" :disabled="busy||readonly"/>查看报表</label><label><input v-model="p.exportCanRead" type="checkbox" :disabled="busy||readonly"/>导出可见资料</label><label><input v-model="p.importCanWrite" type="checkbox" :disabled="busy||readonly||p.roleCode==='VIEWER'"/>批量导入客户</label><label><input v-model="p.attachmentCanRead" type="checkbox" :disabled="busy||readonly" @change="normalizeModules(p)"/>查看附件</label><label><input v-model="p.attachmentCanWrite" type="checkbox" :disabled="busy||readonly||!p.attachmentCanRead||p.roleCode==='VIEWER'"/>上传与删除附件</label></div><div class="admin-policy-checks"><label><input v-model="p.productCanRead" type="checkbox" :disabled="busy||readonly" @change="normalizeModules(p)"/>读取产品目录</label><label><input v-model="p.productCanWrite" type="checkbox" :disabled="busy||readonly||!p.productCanRead||p.roleCode==='VIEWER'"/>维护产品目录</label><label><input v-model="p.quoteCanRead" type="checkbox" :disabled="busy||readonly" @change="normalizeModules(p)"/>读取报价</label><label><input v-model="p.quoteCanWrite" type="checkbox" :disabled="busy||readonly||!p.quoteCanRead||p.roleCode==='VIEWER'"/>管理报价</label><label><input v-model="p.quotePdfCanExport" type="checkbox" :disabled="busy||readonly||!p.quoteCanRead||p.roleCode==='VIEWER'"/>导出报价 PDF</label><label><input v-model="p.quoteCanApprove" type="checkbox" :disabled="busy||readonly||!p.quoteCanRead||p.roleCode!=='SALES_MANAGER'"/>审批指定报价（销售经理）</label></div><div class="admin-policy-checks"><label><input v-model="p.contractCanRead" type="checkbox" :disabled="busy||readonly" @change="normalizeModules(p)"/>读取合同</label><label><input v-model="p.contractCanWrite" type="checkbox" :disabled="busy||readonly||!p.contractCanRead||p.roleCode==='VIEWER'" @change="normalizeModules(p)"/>管理合同草稿与签订</label><label><input v-model="p.contractCanAmend" type="checkbox" :disabled="busy||readonly||!p.contractCanRead||p.roleCode!=='SALES_MANAGER'||!p.contractCanWrite" @change="normalizeModules(p)"/>受控合同变更（经理）</label><label><input v-model="p.receiptCanRead" type="checkbox" :disabled="busy||readonly||!p.contractCanRead" @change="normalizeModules(p)"/>读取回款与对账</label><label><input v-model="p.receiptCanWrite" type="checkbox" :disabled="busy||readonly||!p.contractCanRead||p.roleCode==='VIEWER'||!p.receiptCanRead" @change="normalizeModules(p)"/>登记待确认回款</label><label><input v-model="p.receiptCanConfirm" type="checkbox" :disabled="busy||readonly||!p.contractCanRead||p.roleCode!=='SALES_MANAGER'||!p.receiptCanRead" @change="normalizeModules(p)"/>确认他人到账（经理）</label><label><input v-model="p.receiptCanReverse" type="checkbox" :disabled="busy||readonly||!p.contractCanRead||p.roleCode!=='SALES_MANAGER'||!p.receiptCanRead" @change="normalizeModules(p)"/>冲正已确认回款（经理）</label><label><input v-model="p.tradeCanExport" type="checkbox" :disabled="busy||readonly||!p.contractCanRead||p.roleCode==='VIEWER'" @change="normalizeModules(p)"/>导出合同与对账</label></div><p class="admin-muted">合同和回款还受客户 / 商机及记录范围限制。登记回款与确认到账是独立权限，登记人不能确认自己的记录。导出遵循记录范围与字段可见性；导入还需客户写入权限。附件受所属客户 / 商机权限限制。商机按模块范围及客户权限共同访问；关联客户或商机的跟进与待办还需对应资料权限。联系人需同时拥有所属客户的权限；线索按下方记录范围访问，暂不支持单独共享。信用代码和客户备注设置只作用于客户字段。</p><div class="admin-form-grid"><label class="wide">记录范围<select v-model="p.recordScope" :disabled="busy||readonly"><option v-for="(label,key) in scopeNames" :key="key" :value="key">{{label}}</option></select></label><label>信用代码<select v-model="p.creditAccess" :disabled="busy||readonly"><option v-for="(label,key) in fieldNames" :key="key" :value="key" :disabled="key==='WRITE'&&!p.canWrite">{{label}}</option></select></label><label>客户备注<select v-model="p.descriptionAccess" :disabled="busy||readonly"><option v-for="(label,key) in fieldNames" :key="key" :value="key" :disabled="key==='WRITE'&&!p.canWrite">{{label}}</option></select></label></div><button class="btn primary" :disabled="busy||readonly" @click="savePolicy(p)">保存角色权限</button></article></section>
  <section v-else-if="section==='sales-rules'" class="card admin-data-card"><div class="admin-note compact"><Icon name="shield"/><div><strong>保有量在新增、转交线索或客户时实时校验</strong><p>“阻止”会拒绝超限分配；“预警”允许继续并留下管理员可追踪的预警记录。</p></div></div><div v-if="resourceAlerts.some(a=>!a.readAt)" class="resource-alerts"><article v-for="a in resourceAlerts.filter(a=>!a.readAt).slice(0,5)" :key="a.id"><Icon name="bell"/><span><strong>{{a.memberName}} 的{{a.resourceType==='LEAD'?'线索':'客户'}}保有量已超限</strong><small>{{date(a.createdAt)}} · 当前 {{a.currentCount}} / 上限 {{a.limitValue}}</small></span><button class="text-button" :disabled="busy" @click="readResourceAlert(a)">标记已处理</button></article></div><div class="table-scroll"><table class="resource-table"><thead><tr><th>销售人员</th><th>线索保有量</th><th>客户保有量</th><th>超限处理</th><th>未跟进判定</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.memberId"><td><strong>{{r.memberName}}</strong><small>{{r.employeeCode||'未设置工号'}} · {{r.jobTitle||'未设置岗位'}} · {{r.salesRegion||'未设置区域'}}</small></td><td><div class="rule-number"><input v-model.number="r.leadLimit" type="number" min="1" max="100000" :disabled="busy||readonly"/><small>当前 {{r.leadCount}} 条</small></div></td><td><div class="rule-number"><input v-model.number="r.customerLimit" type="number" min="1" max="100000" :disabled="busy||readonly"/><small>当前 {{r.customerCount}} 家</small></div></td><td><select v-model="r.overflowAction" :disabled="busy||readonly"><option value="BLOCK">阻止分配</option><option value="WARN">允许并预警</option></select></td><td><div class="rule-stale"><label>线索 <input v-model.number="r.leadStaleDays" type="number" min="1" max="365" :disabled="busy||readonly"/> 天</label><label>客户 <input v-model.number="r.customerStaleDays" type="number" min="1" max="365" :disabled="busy||readonly"/> 天</label></div></td><td><button class="text-button" :disabled="busy||readonly" @click="saveResourceRule(r)">保存规则</button></td></tr></tbody></table></div><div v-if="!rows.length" class="admin-empty">暂无成员规则</div></section>
  <section v-else class="card admin-data-card"><div class="table-scroll"><table>
   <template v-if="section==='platform-tenants'"><thead><tr><th>企业</th><th>套餐</th><th>有效成员</th><th>客户用量</th><th>订阅到期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="t in rows" :key="t.id"><td><strong>{{t.name}}</strong><small>{{t.code}} · {{t.industry||'未填写行业'}}</small></td><td>{{t.planName}}</td><td>{{t.activeMemberCount}} / {{t.seatLimit}}</td><td>{{t.customerCount}} / {{t.customerLimit}}</td><td>{{date(t.subscriptionEnd)}}</td><td><span class="badge" :class="tenantState(t)==='正常使用'?'green':'amber'">{{tenantState(t)}}</span></td><td><button class="text-button" :disabled="busy" @click="open('subscription',t)">调整套餐 / 状态</button></td></tr></tbody></template>
   <template v-else-if="section==='platform-plans'"><thead><tr><th>套餐</th><th>月费</th><th>成员额度</th><th>客户额度</th><th>附件容量</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in rows" :key="p.id"><td><strong>{{p.name}}</strong><small>{{p.code}}</small></td><td>{{money(p.monthlyPriceCents)}}</td><td>{{p.seatLimit}}</td><td>{{p.customerLimit}}</td><td>{{Math.round(p.storageLimitBytes/1048576)}} MB</td><td><span class="badge" :class="p.active?'green':'neutral'">{{p.active?'可开通':'已停用'}}</span></td><td><button class="text-button" :disabled="busy" @click="open('plan',p)">编辑</button></td></tr></tbody></template>
   <template v-else-if="section==='members'"><thead><tr><th>成员</th><th>业务档案</th><th>部门 / 角色</th><th>服务状态</th><th>账号状态</th><th>操作</th></tr></thead><tbody><tr v-for="m in rows" :key="m.id"><td><strong>{{m.displayName}}</strong><span v-if="m.id===memberId" class="badge neutral">当前成员</span><small>{{m.username}}<span v-if="m.mustChangePassword"> · 首次登录需改密</span></small></td><td>{{m.employeeCode||'未设置工号'}}<small>{{m.jobTitle||'未设置岗位'}} · {{m.salesRegion||'未设置区域'}}</small></td><td>{{m.departmentName||'未分配部门'}}<div class="admin-role-tags"><span v-for="r in m.roles" :key="r" class="badge neutral">{{roleNames[r]}}</span></div></td><td><span class="badge" :class="m.serviceStatus==='AVAILABLE'?'green':'neutral'">{{({AVAILABLE:'可服务',BUSY:'忙碌',OFF_DUTY:'离岗'} as Record<string,string>)[m.serviceStatus]}}</span></td><td><span class="badge" :class="m.status==='ACTIVE'?'green':'neutral'">{{m.status==='ACTIVE'?'有效':'已停用'}}</span></td><td><button class="text-button" :disabled="busy||readonly" @click="open('member',m)">编辑成员</button></td></tr></tbody></template>
   <template v-else-if="section==='departments'"><thead><tr><th>部门</th><th>上级部门</th><th>有效成员</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="d in rows" :key="d.id"><td><strong>{{d.name}}</strong></td><td>{{rows.find(r=>r.id===d.parentId)?.name||'顶级部门'}}</td><td>{{d.memberCount}}</td><td><span class="badge" :class="d.active?'green':'neutral'">{{d.active?'有效':'已停用'}}</span></td><td><button class="text-button" :disabled="busy||readonly" @click="open('department',d)">编辑部门</button></td></tr></tbody></template>
   <template v-else-if="section==='billing'||section==='platform-renewals'"><thead><tr><th v-if="section==='platform-renewals'">企业</th><th>申请时间</th><th>套餐 / 周期</th><th>申请金额</th><th>状态</th><th>处理结果</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td v-if="section==='platform-renewals'">{{r.tenantName}}</td><td>{{date(r.createdAt)}}</td><td>{{r.planName}} · {{r.months}} 个月</td><td>{{money(r.amountCents)}}</td><td><span class="badge" :class="r.status==='CONFIRMED'?'green':r.status==='PENDING'?'amber':'neutral'">{{({PENDING:'待审核',CONFIRMED:'已续费',REJECTED:'已驳回',CANCELLED:'已取消'} as Record<string,string>)[r.status]}}</span></td><td>{{r.renewedUntil?'到期：'+date(r.renewedUntil):r.decisionReason||'—'}}</td><td><button v-if="r.status==='PENDING'&&section==='billing'" class="text-button" :disabled="busy" @click="cancel(r)">取消申请</button><button v-if="r.status==='PENDING'&&section==='platform-renewals'" class="text-button" :disabled="busy" @click="open('decision',r);form.status='CONFIRMED'">处理申请</button></td></tr></tbody></template>
   <template v-else-if="section==='support'||section==='platform-support'"><thead><tr><th>{{section==='support'?'运营人员':'授权企业'}}</th><th>支持目的</th><th>字段范围</th><th>到期时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="g in rows" :key="g.id"><td><strong>{{section==='support'?g.operatorName:g.tenantName}}</strong></td><td>{{g.reason}}</td><td>客户基础字段<small>{{g.allowCredit?'含信用代码':'不含信用代码'}} · {{g.allowDescription?'含客户备注':'不含客户备注'}}</small></td><td>{{date(g.expiresAt)}}</td><td><span class="badge" :class="grantState(g)==='授权有效'?'green':'neutral'">{{grantState(g)}}</span></td><td><div class="admin-row-actions"><button v-if="section==='support'" class="text-button" :disabled="busy" @click="showAccess(g)">访问记录</button><button v-if="section==='support'&&grantState(g)==='授权有效'" class="text-button danger-text" :disabled="busy" @click="revoke(g)">撤销授权</button><button v-if="section==='platform-support'" class="text-button" :disabled="busy||grantState(g)!=='授权有效'" @click="enter(g)">进入只读工作区</button></div></td></tr></tbody></template>
   <template v-else-if="section==='platform-accounts'"><thead><tr><th>账号</th><th>姓名</th><th>平台权限</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in rows" :key="u.id"><td><strong>{{u.username}}</strong><small v-if="u.mustChangePassword">下次登录需修改密码</small></td><td>{{u.displayName}}</td><td>{{u.isPlatformOperator?'平台运营':'普通登录账号'}}</td><td>{{u.status==='ACTIVE'?'有效':'已停用'}}</td><td><button class="text-button" :disabled="busy" @click="open('reset',u)">重置密码</button><button class="text-button" :disabled="busy" @click="open('recovery',u)">绑定找回邮箱</button><small>{{u.recoveryEmailVerifiedAt?'已绑定核验邮箱':'尚未绑定找回邮箱'}}</small></td></tr></tbody></template>
   <template v-else><thead><tr><th>时间</th><th>执行人</th><th v-if="section==='platform-audits'">企业</th><th>动作</th><th>追踪编号</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td>{{date(a.createdAt)}}</td><td>{{a.actorName}}</td><td v-if="section==='platform-audits'">{{a.tenantName||'平台操作'}}</td><td>{{a.action}}</td><td><code>{{a.traceId?.slice(0,8)}}</code></td></tr></tbody></template>
  </table></div><div v-if="!rows.length" class="admin-empty">{{busy?'正在读取服务端数据…':'当前没有记录'}}</div></section>
  <Teleport to="body"><div v-if="dialog" class="modal-backdrop" @click.self="close"><section ref="modal" class="admin-dialog" role="dialog" aria-modal="true" aria-labelledby="admin-dialog-title"><div class="admin-dialog-heading"><h2 id="admin-dialog-title">{{({tenant:'开通企业',subscription:'调整订阅与状态',plan:editing?'编辑套餐':'创建套餐',member:editing?'编辑成员':'创建成员',department:editing?'编辑部门':'新增部门',renewal:'提交续费申请',decision:'处理人工续费申请',grant:'授权只读支持',reset:'重置登录密码',recovery:'绑定找回邮箱',access:'支持访问记录'} as Record<string,string>)[dialog]}}</h2><button class="icon-button" aria-label="关闭" :disabled="busy" @click="close"><Icon name="close"/></button></div>
   <div v-if="dialog==='access'" class="admin-dialog-body"><p class="admin-muted">这里只记录访问时间、动作与追踪编号，不记录客户正文。</p><div v-for="a in access" :key="a.id" class="admin-access-row"><span>{{date(a.createdAt)}}</span><strong>{{a.action==='CUSTOMER_LIST'?'查看客户列表':'查看客户资料'}}</strong><code>{{a.traceId?.slice(0,8)}}</code></div><div v-if="!access.length" class="admin-empty">暂无成功访问记录</div></div>
   <form v-else class="admin-dialog-form" @submit.prevent="save"><div class="admin-dialog-body"><fieldset :disabled="busy"><div class="admin-form-grid">
    <template v-if="dialog==='tenant'"><label>企业编码<input v-model="form.code" required pattern="[a-z0-9][a-z0-9_-]{1,39}" maxlength="40" placeholder="如：company-001"/></label><label>企业名称<input v-model="form.name" required maxlength="200"/></label><label>行业<input v-model="form.industry" maxlength="80"/></label><label>试用天数<input v-model.number="form.trialDays" type="number" min="1" max="365" required/></label><label class="wide">套餐<select v-model="form.planId" required><option v-for="p in activePlans" :key="p.id" :value="p.id">{{p.name}} · {{p.seatLimit}} 位成员 / {{p.customerLimit}} 家客户</option></select></label><label>初始管理员账号<input v-model="form.adminUsername" autocomplete="off" required maxlength="128"/></label><label>管理员姓名<input v-model="form.adminName" required maxlength="100"/></label><label class="wide">初始密码<input v-model="form.initialPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="72"/><small>首次登录必须修改密码。不会发送邮件，请由负责人交付账号。</small></label></template>
    <template v-if="dialog==='subscription'"><label class="wide">企业<input :value="editing?.name" disabled/></label><label class="wide">套餐<select v-model="form.planId"><option v-for="p in plans" :key="p.id" :value="p.id" :disabled="!p.active">{{p.name}} · {{p.seatLimit}} 位成员 / {{p.customerLimit}} 家客户</option></select></label><label class="wide">使用状态<select v-model="form.status"><option value="ACTIVE">正常使用</option><option value="SUSPENDED">暂停企业业务访问</option></select><small>暂停立即阻止业务访问；到期续费需通过续费申请确认。</small></label></template>
    <template v-if="dialog==='plan'"><label>套餐编码<input v-model="form.code" required pattern="[a-z0-9][a-z0-9_-]{1,39}" maxlength="40"/></label><label>套餐名称<input v-model="form.name" required maxlength="100"/></label><label>月费（元）<input v-model="form.price" inputmode="decimal" required/></label><label>成员额度<input v-model.number="form.seatLimit" type="number" min="1" max="10000" required/></label><label>客户额度<input v-model.number="form.customerLimit" type="number" min="1" max="10000000" required/></label><label>附件容量（MB）<input v-model.number="form.storageMB" type="number" min="1" max="1048576" required/></label><label>套餐状态<select v-model="form.active"><option :value="true">可开通</option><option :value="false">停用新开通</option></select></label><p class="admin-muted wide">停用不取消已有企业订阅。降低额度时不能低于已订阅企业的实际用量。</p></template>
    <template v-if="dialog==='member'"><label>成员姓名<input v-model="form.name" required maxlength="100"/></label><label>登录账号<input v-model="form.username" :disabled="!!editing" required maxlength="128" autocomplete="off"/></label><label>员工工号<input v-model="form.employeeCode" maxlength="40" placeholder="如 XS-008"/></label><label>岗位<input v-model="form.jobTitle" maxlength="100" placeholder="如 大客户经理"/></label><label>销售区域<input v-model="form.salesRegion" maxlength="100" placeholder="如 华东区"/></label><label>服务状态<select v-model="form.serviceStatus"><option value="AVAILABLE">可服务</option><option value="BUSY">忙碌</option><option value="OFF_DUTY">离岗</option></select></label><label class="wide">所属部门<select v-model="form.departmentId"><option value="">未分配部门</option><option v-for="d in departments.filter(d=>d.active)" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label v-if="!editing" class="wide">初始密码<input v-model="form.initialPassword" type="password" required minlength="12" maxlength="72" autocomplete="new-password"/><small>新账号首次登录必须修改初始密码。</small></label><label v-if="editing" class="wide">成员状态<select v-model="form.status"><option value="ACTIVE">有效</option><option value="DISABLED">停用并释放成员名额</option></select></label><label v-if="editing&&form.status==='DISABLED'&&editing.status==='ACTIVE'" class="wide">停用后资源接收人<select v-model="form.successorMemberId" required><option value="">选择有效成员</option><option v-for="m in rows.filter(m=>m.status==='ACTIVE'&&m.id!==editing?.id)" :key="m.id" :value="m.id">{{m.displayName}}</option></select><small>停用时，未入池线索与客户在同一事务中转交；接收人必须具备对应写入权限及保有量。处理失败则不会停用成员。</small></label><div class="wide"><span class="admin-field-label">成员角色（至少选择一个）</span><div class="admin-role-options"><label v-for="(label,key) in roleNames" :key="key"><input v-model="form.roles" type="checkbox" :value="key"/>{{label}}</label></div><p class="admin-muted">企业管理员负责管理组织；销售经理负责客户业务。可以同时授予这两种角色。</p></div></template>
    <template v-if="dialog==='department'"><label class="wide">部门名称<input v-model="form.name" required maxlength="100"/></label><label class="wide">上级部门<select v-model="form.parentId"><option value="">顶级部门</option><option v-for="d in rows.filter(d=>d.active&&d.id!==editing?.id)" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label class="wide">部门状态<select v-model="form.active"><option :value="true">有效</option><option :value="false">停用</option></select></label></template>
    <template v-if="dialog==='renewal'"><label class="wide">续费周期<select v-model.number="form.months"><option :value="1">1 个月</option><option :value="3">3 个月</option><option :value="6">6 个月</option><option :value="12">12 个月</option></select></label><div class="admin-quote wide"><span>申请金额</span><strong>{{money((summary?.monthlyPriceCents??0)*form.months)}}</strong><small>金额提交后固定。不会自动扣款。</small></div></template>
    <template v-if="dialog==='decision'"><div class="admin-quote wide"><span>{{editing?.tenantName}} · {{editing?.months}} 个月</span><strong>{{money(editing?.amountCents??0)}}</strong><small>请在实际核实收款后确认；重复确认不会重复延长订阅。</small></div><label class="wide">处理结果<select v-model="form.status"><option value="CONFIRMED">已核实收款，确认续费</option><option value="REJECTED">驳回申请</option></select></label><label v-if="form.status==='CONFIRMED'" class="wide">收款凭据编号<input v-model="form.paymentReference" required maxlength="100" placeholder="如银行流水或收款登记编号"/></label><label class="wide">{{form.status==='REJECTED'?'驳回原因':'处理备注'}}<textarea v-model="form.reason" :required="form.status==='REJECTED'" rows="3" maxlength="300"></textarea></label></template>
    <template v-if="dialog==='grant'"><label class="wide">获授权运营人员<select v-model="form.operatorUserId" required><option v-for="u in operators" :key="u.id" :value="u.id">{{u.displayName}} · {{u.username}}</option></select></label><label>有效时长（小时）<input v-model.number="form.hours" type="number" min="1" max="4" required/></label><label class="wide">授权目的<textarea v-model="form.reason" required rows="3" maxlength="300"></textarea></label><div class="wide admin-role-options"><label><input v-model="form.allowCredit" type="checkbox"/>允许查看信用代码</label><label><input v-model="form.allowDescription" type="checkbox"/>允许查看客户备注</label></div><p class="admin-muted wide">授权仅允许读取客户资料，最多4小时；不能修改客户、组织、权限或订阅。你可随时撤销并查看访问记录。</p></template>
    <template v-if="dialog==='recovery'"><label class="wide">账号<input :value="editing?.username" disabled/></label><label class="wide">已核验的恢复邮箱<input v-model="form.recoveryEmail" type="email" required maxlength="254"/></label><label class="wide">核验与绑定说明<textarea v-model="form.reason" required maxlength="300" rows="3"></textarea></label><p class="admin-muted wide">请先确认该邮箱属于账号使用人。绑定后会撤销该账号已有会话和旧找回链接；邮件服务启用后可自助找回。</p></template><template v-if="dialog==='reset'"><label class="wide">登录账号<input :value="editing?.username" disabled/></label><label class="wide">新的初始密码<input v-model="form.newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="72" required/></label><p class="admin-muted wide">该账号在所有企业的登录会话都会失效，下次登录必须修改此初始密码。</p></template>
   </div></fieldset><div v-if="error" class="admin-alert error" role="alert">{{error}}</div></div><div class="admin-dialog-footer"><span>所有修改均由服务端校验</span><button class="btn secondary" type="button" :disabled="busy" @click="close">取消</button><button class="btn primary" :disabled="busy">{{busy?'正在保存…':'确认保存'}}</button></div></form>
  </section></div></Teleport>
 </div>
</template>

